-- SQL_t03_plans_for_eight_repaired_tools.sql — webdesign.co.uk
--
-- A PLAN with a ```criteria fence for each of the eight tools repaired on
-- 2026-07-29 (insight-injector already has one, from SQL_t01).
--
-- THIS IS NOT PAPERWORK. The acceptance ladder's eligibility was widened the
-- same day so that a ported tool page is visible to it at all, keyed by its
-- PAGE rather than by cc.function (all 63 share the literal 'ported-page').
-- But both tiers are criteria-gated: without a doc_plans row carrying a fence,
-- Tier 4 emits nothing and Tier 2 writes a needs_criteria note. So the PLAN is
-- the act that makes the repair permanent — without it the tool goes back to
-- being unwatched the moment this session ends.
--
-- Each PLAN carries a 'deliberate decisions — do not re-fix' section. Those are
-- the traps a future fixer would otherwise walk into: rls-architect's selects
-- are read by option TEXT, seo-injector's by value; pasteboard genuinely
-- defines saveHistory while its two siblings were wrong to call it.
--
-- Bodies travel as base64 and are decoded in Postgres. The plans contain
-- backticks, braces, quotes and JSON; dollar-quoting that by hand is how a
-- generator in this workstream corrupted itself earlier.

\set ON_ERROR_STOP on

BEGIN;

INSERT INTO doc_plans (subject_type, subject_key, body, source, created_by, is_current)
VALUES ('tool', 'animated-favicon', convert_from(decode('','base64'),'UTF8'),
        'webdesign_tools_repair', 'webdesign_couk_thread', true)
ON CONFLICT (subject_type, subject_key) WHERE is_current DO NOTHING;

INSERT INTO doc_notes (subject_type, subject_key, body, categories, source, created_by)
VALUES ('tool', 'animated-favicon', convert_from(decode('','base64'),'UTF8'),
        '["repair","tools-programme"]'::jsonb, 'webdesign_tools_repair', 'webdesign_couk_thread');

