        '["repair","tools-programme"]'::jsonb, 'webdesign_tools_repair', 'webdesign_couk_thread');

DO $verify$
DECLARE v_missing text;
BEGIN
    SELECT string_agg(k, ', ') INTO v_missing FROM unnest(ARRAY['animated-favicon', 'asset-formatter', 'logic-architect', 'mind-map', 'monolith-splitter', 'pasteboard', 'rls-architect', 'seo-injector']) k
     WHERE NOT EXISTS (SELECT 1 FROM doc_plans dp
        WHERE dp.subject_type='tool' AND dp.subject_key=k AND dp.is_current
          AND dp.body LIKE '%```criteria%');
    IF v_missing IS NOT NULL THEN
        RAISE EXCEPTION 'these tools have no current PLAN with a criteria fence: %', v_missing;
    END IF;
    RAISE NOTICE 'all eight PLANs recorded with criteria fences; the ladder can now test them';
END $verify$;

COMMIT;
